from __future__ import annotations

import enum
from typing import Dict
from urllib.parse import urlparse, urlunparse

import structlog

structlogger = structlog.get_logger()

# Stand-in for a URL that could not be parsed, and so could not be selectively
# stripped of its credentials.
REDACTED_URL = "<redacted-url>"


class UrlSchema(enum.Enum):
    HTTP = "http"
    HTTPS = "https"
    FILE = "file"
    FTP = "ftp"
    SFTP = "sftp"
    GRPC = "grpc"
    UNKNOWN = "unknown"
    NOT_SPECIFIED = "not_specified"

    @property
    def available_schemas(self) -> Dict[str, UrlSchema]:
        """Get all available URL schemas except for the unknown schema."""
        return {
            schema.value: schema for schema in UrlSchema if schema != UrlSchema.UNKNOWN
        }


def get_url_schema(url: str) -> UrlSchema:
    """Get the schema of a URL.

    Args:
        url: The URL to parse.

    Returns:
        The schema of the URL.
    """
    parsed_url = urlparse(url)

    if parsed_url.scheme == "":
        return UrlSchema.NOT_SPECIFIED

    try:
        return UrlSchema(parsed_url.scheme)
    except ValueError:
        structlogger.warn(
            "rasa.utils.url_tools.get_url_schema.unknown_schema",
            event_info=f"Unknown URL schema '{parsed_url.scheme}'. "
            f"Returning 'unknown'.",
        )

        return UrlSchema.UNKNOWN


def strip_url_credentials(url: str) -> str:
    """Remove embedded credentials from a URL, keeping its non-secret parts.

    Connection strings routinely carry secrets in the userinfo component
    (``redis://user:password@host:6379/0``) or in query parameters
    (``https://host/v1?api-key=...``). Both are dropped, along with the
    fragment, while the scheme, host, port and path are preserved so the value
    stays useful for diagnostics and analytics.

    Args:
        url: The URL to sanitize.

    Returns:
        The URL without userinfo, params, query string or fragment. A value that has no
        network location (a bare string rather than a URL), or nothing to
        remove, is returned unchanged; a value that cannot be parsed at all is
        replaced wholesale by `REDACTED_URL`. The function therefore either
        strips something or returns its input as-is.
    """
    try:
        # Strip first: a trailing space alone makes the `port` lookup below raise,
        # which would otherwise discard a perfectly valid URL.
        parsed = urlparse(url.strip())
        # `port` is a property that re-parses and raises on a malformed port.
        port = parsed.port
    except ValueError:
        # Not parseable as a URL. There is nothing safe to selectively strip,
        # so drop the whole value rather than risk passing a secret through.
        return REDACTED_URL

    if not parsed.netloc:
        return url

    if not (
        parsed.username
        or parsed.password
        or parsed.query
        or parsed.fragment
        or parsed.params
    ):
        # Nothing to remove, so return the input untouched rather than rebuild
        # it. Rebuilding would lowercase the host, producing two spellings of the
        # same endpoint either side of a release and splitting anything that
        # groups on the value downstream.
        return url

    host = parsed.hostname or ""
    if ":" in host:
        # IPv6 literals must stay bracketed to round-trip through urlunparse.
        host = f"[{host}]"
    netloc = f"{host}:{port}" if port is not None else host

    # `params` is the rarely-used `;key=value` segment that `urlparse` splits out
    # of the last path component. It is dropped for the same reason as the query
    # string: it can carry a credential and cannot be selectively trusted.
    #
    # Note this is scheme-dependent. `urlparse` only splits params for the
    # schemes in `urllib.parse.uses_params` (http, https, ftp, sftp, imap, ...),
    # which are the schemes where `;key=value` is an actual convention. For
    # others, such as `redis://`, a `;` segment stays part of the path and is
    # preserved with it -- deliberately, since stripping arbitrary path
    # content would silently mangle legitimate paths for a shape that has not
    # been observed in practice.
    return urlunparse(parsed._replace(netloc=netloc, params="", query="", fragment=""))
